#!/usr/bin/env python3
import json, pathlib
C = pathlib.Path("content")
wire = json.loads((C/"wire.json").read_text())
record = json.loads((C/"record.json").read_text())
articles = json.loads((C/"articles.json").read_text())

# ---- standards housekeeping: caratcheck 2026-08-14 §4 flagged two figures on
# ---- a-the-platinum-hold-ends attributed to the right organisation but the wrong page.
# ---- Not a FOR CORRECTION TODAY item and no figure is wrong, so no correction note is
# ---- printed; the two specific source pages are added to the article's sources list.
fixed = False
for a in articles:
    if a["slug"] == "the-platinum-hold-ends":
        have = {s["url"] for s in a["sources"]}
        for t, u in [
            ("Platinum — price, chart, historical data (cited for the $1,737.70 reading of 14 August 2026)",
             "https://tradingeconomics.com/commodity/platinum"),
            ("Palladium prices today per ounce — JM Bullion (cited for the $1,336.71 reading of 14 August 2026)",
             "https://www.jmbullion.com/charts/palladium-price/"),
        ]:
            if u not in have:
                a["sources"].append({"title": t, "url": u}); fixed = True
(C/"articles.json").write_text(json.dumps(articles, ensure_ascii=False, indent=1))
print("platinum-hold-ends citation completeness fix applied:", fixed)

wire["date_line"] = "Monday, August 17, 2026"
